export function getSanskritChapterByNumber(num) {
  return DAV_SANSKRIT_SURABHI_CLASS8.find(c => Number(c.num) === Number(num)) || DAV_SANSKRIT_SURABHI_CLASS8[0];
}

export function getDhatuRoopByRoot(root) {
  return SANSKRIT_DHATU_ROOP_BANK[root] || null;
}

export function getShabdaRoopByName(name) {
  return SANSKRIT_SHABDA_ROOP_BANK[name] || null;
}
